export type RichTextBlock = {
    type: "paragraph";
    children: RichTextInline[];
} | {
    type: "heading";
    level: 1 | 2 | 3 | 4 | 5 | 6;
    children: RichTextInline[];
} | {
    type: "code-fence";
    code: string;
    lang: string | undefined;
    closed: boolean;
} | {
    type: "list";
    ordered: boolean;
    start: number | undefined;
    items: RichTextListItem[];
} | {
    type: "table";
    align: (RichTextTableAlign | undefined)[];
    header: RichTextTableRow;
    rows: RichTextTableRow[];
};

export type RichTextInline = {
    type: "text";
    text: string;
} | {
    type: "break";
} | {
    type: "strong";
    children: RichTextInline[];
    closed: boolean;
} | {
    type: "em";
    children: RichTextInline[];
    closed: boolean;
} | {
    type: "code";
    code: string;
    closed: boolean;
} | {
    type: "link";
    children: RichTextInline[];
    href: string | undefined;
    rawHref: string;
    closed: boolean;
};
